208	    const gitEnv = pathspecEnv();
209	    // Exclusions in `git add` do not remove paths that were already staged.
210	    // Restore only the internal state entries in the index, leaving their working
211	    // tree contents untouched, before staging the user's workspace changes.
212	    const head = spawnSync("git", ["rev-parse", "--verify", "--quiet", "HEAD"], {
213	      cwd: workspace,
214	      env: gitEnv,
215	      stdio: "ignore",
216	    });
217	    if (head.error) throw head.error;
218	    if (head.status === 0) {
219	      execFileSync("git", ["reset", "--quiet", "HEAD", "--", ...NEXUS_STATE], {
220	        cwd: workspace,
221	        env: gitEnv,
222	        stdio: ["pipe", "pipe", "pipe"],
223	      });
224	    } else {
225	      // A newly initialized repository has no HEAD tree to reset to. Confirm that
226	      // HEAD is a symbolic ref whose branch does not yet exist before treating it
227	      // as unborn; a broken or detached HEAD must still fail closed.
228	      const headRef = spawnSync("git", ["symbolic-ref", "-q", "HEAD"], {
229	        cwd: workspace,
230	        env: gitEnv,
231	        encoding: "utf-8",
232	        stdio: ["ignore", "pipe", "ignore"],
233	      });
234	      if (headRef.error) throw headRef.error;
235	      if (headRef.status !== 0 || !headRef.stdout.trim()) {
236	        throw new Error("Cannot resolve repository HEAD before excluding Nexus state");
237	      }
238	      const branchRef = headRef.stdout.trim();
239	      const branch = spawnSync("git", ["show-ref", "--verify", "--quiet", branchRef], {
240	        cwd: workspace,
241	        env: gitEnv,
242	        stdio: "ignore",
243	      });
244	      if (branch.error) throw branch.error;
245	      if (branch.status !== 1) {
246	        throw new Error("Repository HEAD is not an unborn branch; refusing to alter the index");
247	      }
248	      // There is no HEAD tree to restore from, so remove only staged .nexus paths
249	      // from the index. --cached preserves their workspace contents.
250	      execFileSync("git", ["rm", "--cached", "-r", "-f", "--ignore-unmatch", "--", ...NEXUS_STATE], {
251	        cwd: workspace,
252	        env: gitEnv,
253	        stdio: ["pipe", "pipe", "pipe"],
254	      });
255	    }
256	    // Internal Nexus state must never enter an automated workspace commit, even if a user's
257	    // .git/info/exclude contains a malformed rule or a later negation that exposes .nexus/.
258	    // Same exclusion set as workspaceStatus(): what the dirty count leaves out is never staged.
259	    execFileSync("git", ["add", "-A", "--", ...NEXUS_STATE_EXCLUDED], {
260	      cwd: workspace,
261	      env: gitEnv,
262	      stdio: ["pipe", "pipe", "pipe"],
263	    });
264	    execFileSync("git", ["commit", "-m", message], {
265	      cwd: workspace,
266	      encoding: "utf-8",
267	      stdio: ["pipe", "pipe", "pipe"],
268	    });
269	    const hash = execSync("git rev-parse --short HEAD", {
270	      cwd: workspace,
271	      encoding: "utf-8",
272	      stdio: ["pipe", "pipe", "ignore"],
273	    }).trim();
274	    return { success: true, hash };
275	  } catch (err: any) {
276	    return { success: false, error: err.message };
277	  }
278	}
